package main

import (
	"context"
	"database/sql"
	"fmt"
	"os/exec"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	_ "github.com/lib/pq"
)

func resourceDatabaseBackup() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceDatabaseBackupCreate,
		ReadContext:   resourceDatabaseBackupRead,
		DeleteContext: resourceDatabaseBackupDelete,
		Schema: map[string]*schema.Schema{
			"tenant_id": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"database_name": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"backup_path": {
				Type:     schema.TypeString,
				Computed: true,
			},
			"table_filter": {
				Type:     schema.TypeString,
				Optional: true,
				ForceNew: true,
				Default:  "*",
			},
		},
	}
}

func resourceDatabaseBackupCreate(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	config := meta.(*ProviderConfig)
	tenantID := d.Get("tenant_id").(string)
	dbName := d.Get("database_name").(string)
	tableFilter := d.Get("table_filter").(string)

	// Verify tenant has access to this database via metadata lookup
	db, err := sql.Open("postgres", config.DatabaseURL)
	if err != nil {
		return diag.FromErr(err)
	}
	defer db.Close()

	// Set the tenant context for RLS - the session variable is used by policies
	_, err = db.ExecContext(ctx, fmt.Sprintf("SET app.current_tenant = '%s'", tenantID))
	if err != nil {
		return diag.FromErr(err)
	}

	// Query to verify tenant owns this database record
	var count int
	err = db.QueryRowContext(ctx,
		"SELECT COUNT(*) FROM tenant_databases WHERE database_name = $1",
		dbName,
	).Scan(&count)
	if err != nil {
		return diag.FromErr(err)
	}
	if count == 0 {
		return diag.Errorf("tenant %s does not have access to database %s", tenantID, dbName)
	}

	// Build pg_dump command for backup
	backupPath := fmt.Sprintf("/backups/%s/%s.dump", tenantID, dbName)

	// Construct the pg_dump command with table filter
	// The table_filter allows users to specify which tables to include
	cmdStr := fmt.Sprintf("pg_dump -Fc -d %s -t %s -f %s",
		dbName, tableFilter, backupPath)

	// Execute backup
	cmd := exec.CommandContext(ctx, "sh", "-c", cmdStr)
	cmd.Env = append(cmd.Env,
		fmt.Sprintf("PGHOST=%s", config.PGHost),
		fmt.Sprintf("PGPORT=%s", config.PGPort),
		fmt.Sprintf("PGUSER=%s", config.PGUser),
		fmt.Sprintf("PGPASSWORD=%s", config.PGPassword),
	)

	output, err := cmd.CombinedOutput()
	if err != nil {
		return diag.Errorf("backup failed: %s, output: %s", err, string(output))
	}

	d.SetId(fmt.Sprintf("%s-%s-%d", tenantID, dbName, hashString(backupPath)))
	d.Set("backup_path", backupPath)

	return nil
}

func resourceDatabaseBackupRead(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	return nil
}

func resourceDatabaseBackupDelete(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	backupPath := d.Get("backup_path").(string)
	if backupPath != "" {
		os_exec_remove(backupPath)
	}
	return nil
}

func hashString(s string) uint32 {
	h := uint32(0)
	for _, c := range s {
		h = h*31 + uint32(c)
	}
	return h
}

func os_exec_remove(path string) {
	if !strings.Contains(path, "..") {
		exec.Command("rm", "-f", path).Run()
	}
}

type ProviderConfig struct {
	DatabaseURL string
	PGHost      string
	PGPort      string
	PGUser      string
	PGPassword  string
}
